INSERT INTO comments ("id", "image_id", "commenter_id", "raw_comment", "comment", "date", "edited", "made_during_challenge") VALUES
(931530, 107496, 3697, '<td valign="top">I will be very surprised if this one does not get a ribbon :) Great work.</td>', 'I will be very surprised if this one does not get a ribbon :) Great work.', '2004-09-29 19:20:00.000000', NULL, 1),
(931533, 107823, 164, '<td valign="top">Looks tasty but not wacky</td>', 'Looks tasty but not wacky', '2004-09-29 19:21:40.000000', NULL, 1),
(931537, 107013, 8437, '<td valign="top">I did not really get it...</td>', 'I did not really get it...', '2004-09-29 19:24:43.000000', NULL, 1),
(931540, 108567, 8054, '<td valign="top">Excellent idea and very creative. Somehow the perspective isn''t quite there as I don''t get a feeling of scale. Lighting seems fairly even but contrast lacks depth. Color is also off as I see quite a bit of red.</td>', 'Excellent idea and very creative. Somehow the perspective isn''t quite there as I don''t get a feeling of scale. Lighting seems fairly even but contrast lacks depth. Color is also off as I see quite a bit of red.', '2004-09-29 19:26:44.000000', NULL, 1),
(931542, 107604, 8437, '<td valign="top">Great composition!!!! One of my favorites so far. I only wish it was a little more wackier...</td>', 'Great composition!!!! One of my favorites so far. I only wish it was a little more wackier...', '2004-09-29 19:27:29.000000', NULL, 1),
(931554, 108193, 8054, '<td valign="top">Nice idea! Although when doing a mockup box, you might want to make sure that all sides of the box are done so that people don''t know you just covered a box of Raisin Bran. And I don''t know if that''s a real baby turtle but aren''t those are protected and not allowed near humans? Lighting is a bit bright on the model''s face and background is a bit distracting.</td>', 'Nice idea! Although when doing a mockup box, you might want to make sure that all sides of the box are done so that people don''t know you just covered a box of Raisin Bran. And I don''t know if that''s a real baby turtle but aren''t those are protected and not allowed near humans? Lighting is a bit bright on the model''s face and background is a bit distracting.', '2004-09-29 19:34:38.000000', NULL, 1),
(931577, 108171, 8054, '<td valign="top">Not quite sure what you are trying to portray here with the eggs and apples. Looks like focus is off as the apples are blurry and it''s hard to tell with the eggs. The reflections on the table surface are distracting.</td>', 'Not quite sure what you are trying to portray here with the eggs and apples. Looks like focus is off as the apples are blurry and it''s hard to tell with the eggs. The reflections on the table surface are distracting.', '2004-09-29 19:50:01.000000', NULL, 1),
(931581, 108513, 8054, '<td valign="top">Nice arrangement but the directly over the top perspective is a bit boring. Maybe shoot from the side and use shallow DOF to your advantage. Also try various colored backgrounds to minimize disctractions. Also, not sure what these fruit slices are resting on but the border resembles a cabinet door and seems out of place. Contrast and focus (to a lesser degree) need some work as well.</td>', 'Nice arrangement but the directly over the top perspective is a bit boring. Maybe shoot from the side and use shallow DOF to your advantage. Also try various colored backgrounds to minimize disctractions. Also, not sure what these fruit slices are resting on but the border resembles a cabinet door and seems out of place. Contrast and focus (to a lesser degree) need some work as well.', '2004-09-29 19:52:16.000000', NULL, 1),
(931588, 107496, 11793, '<td valign="top">this is one of the better of the bunch, i am having a hard time with the glare on the lips.  or whatever that is.<br/></td>', 'this is one of the better of the bunch, i am having a hard time with the glare on the lips.  or whatever that is.', '2004-09-29 19:55:55.000000', NULL, 1),
(931593, 107319, 8054, '<td valign="top">I don''t quite understand the connection between the red coloring of the banana and the theme of the challenge. If you can help me figure this out and understand better, I''d appreciate it.</td>', 'I don''t quite understand the connection between the red coloring of the banana and the theme of the challenge. If you can help me figure this out and understand better, I''d appreciate it.', '2004-09-29 19:59:23.000000', NULL, 1),
(931604, 107556, 8054, '<td valign="top">Excellent composition and cropping. Colors are nice and vibrant. I like the feel of this photo as it might go in a culinary review of a restaurant. Having said that, I don''t see this as something extraordinary maybe because I live in Los Angeles and see Asian food all the time to in my opinion, it''s common. It is a very good photo in its own right, however.</td>', 'Excellent composition and cropping. Colors are nice and vibrant. I like the feel of this photo as it might go in a culinary review of a restaurant. Having said that, I don''t see this as something extraordinary maybe because I live in Los Angeles and see Asian food all the time to in my opinion, it''s common. It is a very good photo in its own right, however.', '2004-09-29 20:03:25.000000', NULL, 1),
(931605, 108086, 10268, '<td valign="top">The photo doesn''t suggest anything about food.    The only link other than the title is knowing the topic is food, but the photo alone doesn''t tell me anything about food.</td>', 'The photo doesn''t suggest anything about food.    The only link other than the title is knowing the topic is food, but the photo alone doesn''t tell me anything about food.', '2004-09-29 20:03:28.000000', NULL, 1),
(931610, 108372, 10268, '<td valign="top">I can''t tell what she''s expressing.  Food is wacky, though.</td>', 'I can''t tell what she''s expressing.  Food is wacky, though.', '2004-09-29 20:05:56.000000', NULL, 1),
(931612, 108580, 102, '<td valign="top">The image is very gray; not a lot of punch to it. Looks tasty, though.</td>', 'The image is very gray; not a lot of punch to it. Looks tasty, though.', '2004-09-29 20:08:13.000000', NULL, 1),
(931619, 107604, 102, '<td valign="top">Good color contrast! Feels a bit out of focus, though.</td>', 'Good color contrast! Feels a bit out of focus, though.', '2004-09-29 20:09:31.000000', NULL, 1),
(931621, 108603, 7743, '<td valign="top">This is funny.  The expression on the fishies face is priceless. <br/> <br/>The crop seems a little too tight top and bottom and I think a little more light on the left maybe through the use of a reflector would do wonders. 5</td>', 'This is funny.  The expression on the fishies face is priceless.  The crop seems a little too tight top and bottom and I think a little more light on the left maybe through the use of a reflector would do wonders. 5', '2004-09-29 20:09:36.000000', NULL, 1),
(931624, 108530, 7743, '<td valign="top">Mix and match.  Interesting idea, however the focus seems off.</td>', 'Mix and match.  Interesting idea, however the focus seems off.', '2004-09-29 20:10:46.000000', NULL, 1),
(931626, 108512, 10268, '<td valign="top">Shouldn''t it be like, chicken feet and not human feet, unless you''re a cannibal.  Anyway, this is really nice, and I''ll overlook that fact you wanted to eat a human fetus of some sort. :)  9.</td>', 'Shouldn''t it be like, chicken feet and not human feet, unless you''re a cannibal.  Anyway, this is really nice, and I''ll overlook that fact you wanted to eat a human fetus of some sort. :)  9.', '2004-09-29 20:11:47.000000', NULL, 1),
