(932123, 108513, 26362, '<td valign="top">Great colors and shapes, it looks quite tasty. These are all combinations that are put together regularly, so I had to score it in the middle. It just doesn''t say wacky to me</td>', 'Great colors and shapes, it looks quite tasty. These are all combinations that are put together regularly, so I had to score it in the middle. It just doesn''t say wacky to me', '2004-09-30 00:46:06.000000', NULL, 1),
(932124, 108040, 18461, '<td valign="top">Nice shot.</td>', 'Nice shot.', '2004-09-30 00:46:35.000000', NULL, 1),
