(933369, 107798, 26526, '<td valign="top">Clever idea! Nice color use and great composition. Maybe deeper dof. We bi- focal contact lens wearers, need all the help we can get.</td>', 'Clever idea! Nice color use and great composition. Maybe deeper dof. We bi- focal contact lens wearers, need all the help we can get.', '2004-09-30 23:31:22.000000', NULL, 1),
(933377, 108581, 26526, '<td valign="top">A very clever idea. Not exactlly crab cakes like I used to. Good photograph, great color, and good focus. Quite busy.  I will rate it higher because of your whacky creativity.</td>', 'A very clever idea. Not exactlly crab cakes like I used to. Good photograph, great color, and good focus. Quite busy.  I will rate it higher because of your whacky creativity.', '2004-09-30 23:40:37.000000', NULL, 1),
(933381, 108306, 26526, '<td valign="top">Would have liked to see this photo more in focus. Can''t recognize the foreground fruit. Very nice color.</td>', 'Would have liked to see this photo more in focus. Can''t recognize the foreground fruit. Very nice color.', '2004-09-30 23:47:07.000000', NULL, 1),
(933390, 107476, 4267, '<td valign="top">the challenge clearly says to photograph food... as you admitted, the brain is fake... so I have a decision... does a representation of food qualify as food and meet the challenge? Something to ponder before I decide...</td>', 'the challenge clearly says to photograph food... as you admitted, the brain is fake... so I have a decision... does a representation of food qualify as food and meet the challenge? Something to ponder before I decide...', '2004-09-30 23:54:53.000000', NULL, 1),
