(937099, 108413, 27524, '<td valign="top">Oho must been dreaming :). Funny idea but have to catch this food first. Real nice lights.</td>', 'Oho must been dreaming :). Funny idea but have to catch this food first. Real nice lights.', '2004-10-02 15:39:54.000000', NULL, 1),
(937106, 108284, 20056, '<td valign="top">nice idea and picture...</td>', 'nice idea and picture...', '2004-10-02 15:42:03.000000', NULL, 1),
