(941232, 108363, 19608, '<td valign="top">Now you''ve done it!  You make okra look good, instead of the slimy tasteless stuff.  Excellent composition and use of the reapeting pattern.  The green works really well with the dark background.</td>', 'Now you''ve done it!  You make okra look good, instead of the slimy tasteless stuff.  Excellent composition and use of the reapeting pattern.  The green works really well with the dark background.', '2004-10-04 16:22:49.000000', NULL, 1),
(941234, 108392, 19608, '<td valign="top">Funny.  How can you even tell it was a beer can?</td>', 'Funny.  How can you even tell it was a beer can?', '2004-10-04 16:23:54.000000', NULL, 1),
(941239, 108513, 19608, '<td valign="top">Well done indeed - creating a nice arrangement of colors and shapes.  My only problem is that the background has a definite gray cast - it would look so much better if it were white.  I expect you shouold finish way towards the top.</td>', 'Well done indeed - creating a nice arrangement of colors and shapes.  My only problem is that the background has a definite gray cast - it would look so much better if it were white.  I expect you shouold finish way towards the top.', '2004-10-04 16:26:47.000000', NULL, 1),
(941243, 108586, 19608, '<td valign="top">Not exactly wacky foods - but the ttle is wacky enough.  Nice image with plenty of detail.  The white semicircle at the base should have been moved out of the way.  Excellent exposure.</td>', 'Not exactly wacky foods - but the ttle is wacky enough.  Nice image with plenty of detail.  The white semicircle at the base should have been moved out of the way.  Excellent exposure.', '2004-10-04 16:28:44.000000', NULL, 1),
(941256, 107496, 19608, '<td valign="top">Supebly done macro - great exposure and DoF.  The botoom lip looks a bit unreak in the center.</td>', 'Supebly done macro - great exposure and DoF.  The botoom lip looks a bit unreak in the center.', '2004-10-04 16:33:24.000000', NULL, 1);
INSERT INTO comments ("id", "image_id", "commenter_id", "raw_comment", "comment", "date", "edited", "made_during_challenge") VALUES
(941259, 108317, 14773, '<td valign="top">I saw this idea on For Better or Worse [TLC] a few months ago...great shot.</td>', 'I saw this idea on For Better or Worse [TLC] a few months ago...great shot.', '2004-10-04 16:34:58.000000', NULL, 1),
(941260, 107962, 14773, '<td valign="top">Very nice, I love starfruit..like this photo just as much. 6.</td>', 'Very nice, I love starfruit..like this photo just as much. 6.', '2004-10-04 16:35:46.000000', NULL, 1),
(941265, 107476, 14773, '<td valign="top">Rice with brains in a sauce, with a lavendar garnish? I can''t remember what ''cerveau'' means, but it looks like brains. *ick* good work.</td>', 'Rice with brains in a sauce, with a lavendar garnish? I can''t remember what ''cerveau'' means, but it looks like brains. *ick* good work.', '2004-10-04 16:37:04.000000', NULL, 1),
