(941269, 108590, 19608, '<td valign="top">Idea is great; color selection is pleasing. It could use a bit sharper focus in spots.</td>', 'Idea is great; color selection is pleasing. It could use a bit sharper focus in spots.', '2004-10-04 16:38:35.000000', NULL, 1),
(941272, 108424, 14773, '<td valign="top">Hilarious concept, lighting needs work, though.6</td>', 'Hilarious concept, lighting needs work, though.6', '2004-10-04 16:38:52.000000', NULL, 1),
