(941288, 108135, 14773, '<td valign="top">Polish sesame seed stuff? Or is that "halva"...can''t remember...</td>', 'Polish sesame seed stuff? Or is that "halva"...can''t remember...', '2004-10-04 16:42:56.000000', NULL, 1),
(941290, 108571, 19608, '<td valign="top">That actually looks like something a restaurant would serve - well done.  I like the very dark background - it makes the subject reall y stand out (but the horizontal line at bottom left is distracting.)  Great idea and execution.</td>', 'That actually looks like something a restaurant would serve - well done.  I like the very dark background - it makes the subject reall y stand out (but the horizontal line at bottom left is distracting.)  Great idea and execution.', '2004-10-04 16:43:29.000000', NULL, 1),
(941292, 108512, 14773, '<td valign="top">I''ve seen this idea before and just get a kick out of it each time.</td>', 'I''ve seen this idea before and just get a kick out of it each time.', '2004-10-04 16:44:29.000000', NULL, 1),
(941303, 107469, 14773, '<td valign="top">I''d still eat 2 of ''em.</td>', 'I''d still eat 2 of ''em.', '2004-10-04 16:46:44.000000', NULL, 1),
